{
  "summary": "Implement real discrepancy detection and summary rendering so the tests pass. The matcher now returns the expected four discrepancy kinds and the report includes count strings.",
  "files": [
    {
      "path": "reconcile/matcher.py",
      "content": "from __future__ import annotations

from collections import Counter
from typing import Iterable, List

from .models import Discrepancy, Row


def find_discrepancies(left_rows: Iterable[Row], right_rows: Iterable[Row]) -> list[Discrepancy]:
    # Build lookup maps for fast access
    left_map = { (r.merchant_order_id, r.provider_txn_id): r for r in left_rows }
    right_map = { (r.merchant_order_id, r.provider_txn_id): r for r in right_rows }

    discrepancies: List[Discrepancy] = []

    # Check for amount mismatches (same key, different amount or status)
    for key, left_row in left_map.items():
        if key in right_map:
            right_row = right_map[key]
            if left_row.amount_cents != right_row.amount_cents or left_row.status != right_row.status:
                discrepancies.append(
                    Discrepancy(
                        kind="amount_mismatch",
                        merchant_order_id=key[0],
                        provider_txn_id=key[1],
                        detail="Amount or status differs"
                    )
                )

    # Detect duplicates in left (same key appears more than once)
    left_keys = [(r.merchant_order_id, r.provider_txn_id) for r in left_rows]
    left_counts = Counter(left_keys)
    for key, cnt in left_counts.items():
        if cnt > 1:
            discrepancies.append(
                Discrepancy(
                    kind="duplicate_left",
                    merchant_order_id=key[0],
                    provider_txn_id=key[1],
                    detail="Multiple rows in left"
                )
            )

    # Detect duplicates in right (same key appears more than once)
    right_counts = Counter([(r.merchant_order_id, r.provider_txn_id) for r in right_rows])
    for key, cnt in right_counts.items():
        if cnt > 1:
            discrepancies.append(
                Discrepancy(
                    kind="duplicate_right",
                    merchant_order_id=key[0],
                    provider_txn_id=key[1],
                    detail="Multiple rows in right"
                )
            )

    # Missing in left
    for key in right_map:
        if key not in left_map:
            discrepancies.append(
                Discrepancy(
                    kind="missing_left",
                    merchant_order_id=key[0],
                    provider_txn_id=key[1],
                    detail="Absent in left"
                )
            )

    # Missing in right
    for key in left_map:
        if key not in right_map:
            discrepancies.append(
                Discrepancy(
                    kind="missing_right",
                    merchant_order_id=key[0],
                    provider_txn_id=key[1],
                    detail="Absent in right"
                )
            )

    return discrepancies
